// TypeScript Version: 4.1

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF)
* for a half-normal distribution.
*
* @param x - input value
* @returns evaluated logcdf
*/
type Unary = ( x: number ) => number;

/**
* Interface for the natural logarithm of the cumulative distribution function
* (CDF) of a half-normal distribution.
*/
interface LogCDF {
	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF)
	* for a half-normal distribution with scale parameter `sigma` at a value `x`.
	*
	* ## Notes
	*
	* -   If `x < 0`, the function returns `-Infinity`.
	* -   If `sigma <= 0`, the function returns `NaN`.
	*
	* @param x - input value
	* @param sigma - scale parameter
	* @returns logarithm of cumulative distribution function
	*
	* @example
	* var y = logcdf( 1.0, 1.0 );
	* // returns ~-0.382
	*
	* @example
	* var y = logcdf( -1.0, 1.0 );
	* // returns -Infinity
	*
	* @example
	* var y = logcdf( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 1.0, NaN );
	* // returns NaN
	*/
	( x: number, sigma: number ): number;

	/**
	* Returns a function for evaluating the natural logarithm of the cumulative
	* distribution function (CDF) for a half-normal distribution.
	*
	* @param sigma - scale parameter
	* @returns logcdf
	*
	* @example
	* var mylogcdf = logcdf.factory( 2.0 );
	* y = mylogcdf( 4.0 );
	* // returns ~-0.0466
	*
	* y = mylogcdf( -1.0 );
	* // returns -Infinity
	*/
	factory( sigma: number ): Unary;
}

/**
* Half-normal distribution natural logarithm of cumulative distribution
* function (CDF).
*
* @param x - input value
* @param sigma - scale parameter
* @returns evaluated logcdf
*
* @example
* var y = logcdf( 1.0, 1.0 );
* // returns ~-0.382
*
* var mylogcdf = logcdf.factory( 2.0 );
* y = mylogcdf( 4.0 );
* // returns ~-0.0466
*/
declare var logcdf: LogCDF;


// EXPORTS //

export = logcdf;
